2	function vec2fromTwoparams(param1, param2) {
3		let vec;
4		if(param1 instanceof Vec2)
5			vec = param1.copy();
6		else if(!isNaN(param1) && !isNaN(param2))
7			vec = new Vec2(param1, param2);
8		else
9			vec = new Vec2(0, 0);
10		return vec;
11	}
12	
13	
14	class Vectory {
15		constructor(x, y) {
16			this.vec = vec2fromTwoparams(x, y);
17		}	
18		set x(x) { this.vec.x = x; }
19		get x() { return this.vec.x; }
20		set y(y) { this.vec.y = y; }
21		get y() { return this.vec.y; }
22	}
23	
24	ECS.Components.Position = class position extends Vectory {
25		constructor(x, y) {
26			super(x, y);
27			this.last = this.vec.copy();
28		}	
29	}
