43	ECS.Components.Sprite = class sprite {
44		constructor(sprite, scene, centered=false) {
45			if(sprite instanceof PIXI.Sprite) {
46				this.sprite = sprite;
47			} else if(sprite instanceof PIXI.Texture) {
48				this.sprite = new PIXI.Sprite(sprite);
49			}
50			this.scene = scene;
51			this.scene.addChild(this.sprite);
52	
53			this.offset = new Vec2(0, 0);
54	
55			if(centered) {
56				this.sprite.anchor.x = 0.5; 	
57			}
58			this.centered = centered;
59		}
60	
61		destroy() {
62			this.scene.removeChild(this.sprite);
63		}
64	}
65	
66	// TODO: do
67	ECS.Components.AnimatedSprite = class animatedSprite {
68		constructor(sheet, scene, centered=false) {
69			this.sheet = sheet;
70			this.sprite = new PIXI.AnimatedSprite(Object.entries(sheet.animations)[0][1]);
71			this.currentAnimation = Object.entries(sheet.animations)[0][0];
72			this.sprite.animationSpeed = 0.1;
73	
74			this.scene = scene;
75			this.scene.addChild(this.sprite);
76			this.sprite.play();
77	
78			this.offset = new Vec2(0, 0);
79	
80			if(centered) {
81				this.sprite.anchor.x = 0.5; 	
82				this.offset.x = -this.sprite.width/2;
83			}
84			this.centered = centered;
85		}
86	
87		destroy() {
88			this.scene.removeChild(this.sprite);
89		}
90	
91		setAnimation(name) {
92			if(this.currentAnimation == name) return;
93			if(!this.sheet.animations[name]) return;
94			this.sprite.stop();
95			this.sprite.textures = this.sheet.animations[name];
96			this.sprite.play();
97			this.currentAnimation = name;
98		}
99	}
100	
