133	ECS.Components.Gravity = class gravity {
134		static defaultGravity = 0.15;
135		static maxGravity = 4;
136		
137		constructor(grav) {
138			if(!grav)
139				this.vec = new Vec2(0, ECS.Components.Gravity.defaultGravity);
