	e.animatedSprite.setAnimation("Attack");
	e.animatedSprite.offset = new Vec2(0, 0);
	e.animatedSprite.sprite.scale.x = dir;
	e.enemyDamager.framesEnabled = 10000;
	e.position.vec = pos.copy();

	setTimeout(() => {
		ECS.removeEntity(e.id);
	}, 2000);
	return e;
}

