	let rightButton = ECS.Blueprints.button("right", 44, 117);
	let leftButton = ECS.Blueprints.button("left", 10, 117);

	ECS.register(jumpButton);
	ECS.register(attackButton);
	ECS.register(rightButton);
	ECS.register(leftButton);
}

