	background: #b2b2b2;
}

#canvas {
	width: 880px;
	height: 720px;

	position: absolute;
	/* top: 50vh;
	left: 50vw;
	transform: translate(-50%, -50%); */
	top: 0;
	left: 50vw;
	transform: translate(-50%, 0);

	image-rendering: -moz-crisp-edges;
  	image-rendering: pixelated;

}

