// Temporary research helper: prints a window of the original PIXI bundle around a
// search token so the compatibility audit can quote exact engine semantics.
const fs = require('fs');
const path = require('path');

const bundle = path.resolve(__dirname, '../../Samurai Slasher/js/lib/pixi.min.js');
const src = fs.readFileSync(bundle, 'utf8');
const token = process.argv[2];
const before = Number(process.argv[3] || 2000);
const after = Number(process.argv[4] || 2000);
const nth = Number(process.argv[5] || 0);

let idx = -1;
for (let i = 0; i <= nth; ++i) idx = src.indexOf(token, idx + 1);
if (idx < 0) {
  console.error('not found: ' + token);
  process.exit(1);
}
console.log(src.slice(Math.max(0, idx - before), idx + after));

